package com.flowdesk.alert.event;
import com.flowdesk.common.tenant.TenantContext;import com.flowdesk.common.tenant.TenantContextScope;import org.springframework.dao.DataAccessException;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.support.TransactionTemplate;import java.time.Clock;import java.time.temporal.ChronoUnit;import java.util.Objects;
final class TicketResultDlqAcceptor{private final TicketResultEnvelopeGuard guard;private final TicketResultRepository repository;private final TransactionTemplate transactions;private final Clock clock=Clock.systemUTC();TicketResultDlqAcceptor(TicketResultEnvelopeGuard g,TicketResultRepository r,PlatformTransactionManager tx){guard=g;repository=r;transactions=new TransactionTemplate(tx);}TicketResultConsumer.Result accept(TicketResultTransportMessage delivery){final AcceptedTicketResult m;try{m=guard.validateDlq(delivery);}catch(TicketResultContractViolation poison){return TicketResultConsumer.Result.ACK;}var context=TenantContext.ofValidatedBrokerMessage(m.tenantId(),AlertEventContract.TICKET_ESTABLISHED.producer(),m.correlationId());try(TenantContextScope ignored=TenantContextScope.open(context)){try{return Objects.requireNonNull(transactions.execute(s->{var duplicate=repository.duplicate(m,true);if(duplicate.kind()!=TicketResultRepository.Kind.NONE)return TicketResultConsumer.Result.ACK;var now=clock.instant().truncatedTo(ChronoUnit.MICROS);repository.insertRecovery(m,"BROKER_RETRIES_EXHAUSTED",now);repository.audit(m,"INCIDENT_TICKET_RESULT_DLQ_ACCEPTED","FAILED","BROKER_RETRIES_EXHAUSTED",now);return TicketResultConsumer.Result.ACK;}));}catch(DataAccessException|IllegalStateException e){return TicketResultConsumer.Result.RETRY;}}}}
